// Palabras clave por tipo de cliente (configurable)
// Cambiar KEYWORDS según el nicho del cliente

const KEYWORDS = [
  'eléctric', 'electric', 'energía', 'energia', 'iluminación', 'iluminacion',
  'subestación', 'subestacion', 'transformador', 'generador',
  'redes', 'cableado', 'medidores', 'PANELES SOLARES', 'fotovoltaic',
  'RETIE', 'NTC 2050', 'montaje', 'mantenimiento eléctrico',
  'obras civiles', 'construcción', 'construccion', 'adecuación',
  'infraestructura', 'vías', 'vias', 'paviment', 'alcantarillado',
  'consultoría', 'consultoria', 'interventoría', 'interventoria',
  'diseño', 'diseno', 'ingeniería', 'ingenieria'
];

const items = $input.all();
const matches = [];

for (const item of items) {
  const desc = (item.json.descripcion_del_proceso || '').toLowerCase();
  const entidad = (item.json.nombre_entidad || '').toLowerCase();
  const tipo = (item.json.tipo_de_contrato || '').toLowerCase();
  const searchText = desc + ' ' + entidad + ' ' + tipo;

  const matched = KEYWORDS.filter(kw => searchText.includes(kw.toLowerCase()));

  if (matched.length > 0) {
    const valor = parseInt(item.json.valor_del_contrato) || 0;
    const valorFormatted = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(valor);

    matches.push({
      json: {
        id_contrato: item.json.id_contrato,
        proceso: item.json.proceso_de_compra,
        entidad: item.json.nombre_entidad,
        descripcion: item.json.descripcion_del_proceso,
        valor: valorFormatted,
        fecha: item.json.fecha_de_firma,
        departamento: item.json.departamento,
        ciudad: item.json.ciudad,
        modalidad: item.json.modalidad_de_contratacion,
        tipo: item.json.tipo_de_contrato,
        url: item.json.urlproceso?.url || `https://community.secop.gov.co/`,
        keywords: matched.join(', '),
        message: `📋 *Nueva Licitación SECOP*\n\n🏛️ *${item.json.nombre_entidad}*\n📍 ${item.json.departamento || ''}, ${item.json.ciudad || ''}\n📝 ${item.json.descripcion_del_proceso?.substring(0, 120)}...\n💰 ${valorFormatted}\n📅 ${item.json.fecha_de_firma?.split('T')[0]}\n🏷️ ${item.json.modalidad_de_contratacion}\n\n🔗 ${item.json.urlproceso?.url || 'https://community.secop.gov.co/'}\n\n⚡ SECOP Alertas`
      }
    });
  }
}

return matches;
